/**
 * File — deprecation chain.
 *
 * Ported from `@wordpress/block-library/src/file/deprecated.js` (v9.43.0).
 * Upstream ships three deprecation entries — they are kept verbatim under
 * the new namespace so legacy `core/file` markup deserializes cleanly
 * after a `core/file` → `artisanpack/file` round-trip via the block
 * transforms in `transforms.ts`.
 */

import type { ReactElement } from 'react';
import clsx from 'clsx';
import {
    __experimentalGetElementClassName,
    RichText,
    useBlockProps,
} from '@wordpress/block-editor';
import { __, sprintf } from '@wordpress/i18n';

interface DeprecatedFileAttributes {
    readonly href?: string;
    readonly fileId?: string;
    readonly fileName?: string;
    readonly textLinkHref?: string;
    readonly textLinkTarget?: string;
    readonly showDownloadButton?: boolean;
    readonly downloadButtonText?: string;
    readonly displayPreview?: boolean;
    readonly previewHeight?: number;
}

// Version of the file block without PR#43050 removing the translated aria-label.
const v3 = {
    attributes: {
        id: {
            type: 'number',
        },
        href: {
            type: 'string',
        },
        fileId: {
            type: 'string',
            source: 'attribute',
            selector: 'a:not([download])',
            attribute: 'id',
        },
        fileName: {
            type: 'string',
            source: 'html',
            selector: 'a:not([download])',
        },
        textLinkHref: {
            type: 'string',
            source: 'attribute',
            selector: 'a:not([download])',
            attribute: 'href',
        },
        textLinkTarget: {
            type: 'string',
            source: 'attribute',
            selector: 'a:not([download])',
            attribute: 'target',
        },
        showDownloadButton: {
            type: 'boolean',
            default: true,
        },
        downloadButtonText: {
            type: 'string',
            source: 'html',
            selector: 'a[download]',
        },
        displayPreview: {
            type: 'boolean',
        },
        previewHeight: {
            type: 'number',
            default: 600,
        },
    },
    supports: {
        anchor: true,
        align: true,
    },
    save({
        attributes,
    }: {
        attributes: DeprecatedFileAttributes;
    }): ReactElement | null {
        const {
            href,
            fileId,
            fileName,
            textLinkHref,
            textLinkTarget,
            showDownloadButton,
            downloadButtonText,
            displayPreview,
            previewHeight,
        } = attributes;

        if (!href) {
            return null;
        }

        const pdfEmbedLabel = RichText.isEmpty(fileName ?? '')
            ? __('PDF embed')
            : sprintf(
                  /* translators: %s: filename. */
                  __('Embed of %s.'),
                  fileName
              );

        const hasFilename = !RichText.isEmpty(fileName ?? '');

        // Only output an `aria-describedby` when the element it's referring to is
        // actually rendered.
        const describedById = hasFilename ? fileId : undefined;

        return (
            <div {...useBlockProps.save()}>
                {displayPreview && (
                    <>
                        <object
                            className="wp-block-file__embed"
                            data={href}
                            type="application/pdf"
                            style={{
                                width: '100%',
                                height: `${previewHeight}px`,
                            }}
                            aria-label={pdfEmbedLabel}
                        />
                    </>
                )}
                {hasFilename && (
                    <a
                        id={describedById}
                        href={textLinkHref}
                        target={textLinkTarget}
                        rel={
                            textLinkTarget ? 'noreferrer noopener' : undefined
                        }
                    >
                        <RichText.Content value={fileName} />
                    </a>
                )}
                {showDownloadButton && (
                    <a
                        href={href}
                        className={clsx(
                            'wp-block-file__button',
                            __experimentalGetElementClassName('button')
                        )}
                        download
                        aria-describedby={describedById}
                    >
                        <RichText.Content value={downloadButtonText} />
                    </a>
                )}
            </div>
        );
    },
};

